static void mh_parse_field_list(const char* path, size_t line_no, pchar* p, pchar end_, MhExport* exp)
{
    MhField* fields = nil;
    size_t count = 0;
    char* ext = nil;
    size_t ext_len = 0;
    ((*exp)).is_struct = false;
    ((*exp)).is_union = false;
    ((*exp)).extends_name = nil;
    ((*exp)).extends_name_len = 0;
    ((*exp)).fields = nil;
    ((*exp)).field_count = 0;
    if (mh_match_word(p, end_, "struct"))
    {
        ((*exp)).is_struct = true;
    }
    else if (mh_match_word(p, end_, "union"))
    {
        ((*exp)).is_union = true;
    }
    else
    {
                return;
    }
    if (mh_match_word(p, end_, "extends"))
    {
        if (!mh_read_ident(p, end_, &ext, &ext_len))
        {
            mh_fatal(path, line_no, "mh_parse_field_list: expected parent type after extends");
        }
        ((*exp)).extends_name = ext;
        ((*exp)).extends_name_len = ext_len;
    }
    if (!mh_match_char(p, end_, '('))
    {
        mh_fatal(path, line_no, "mh_parse_field_list: expected '(' after struct/union");
    }
    mh_parse_field_items(path, line_no, p, end_, &fields, &count);
    if (!mh_match_char(p, end_, ')'))
    {
        mh_fatal(path, line_no, "mh_parse_field_list: expected ')'");
    }
    ((*exp)).fields = fields;
    ((*exp)).field_count = count;
}

static void mh_parse_export_line(const char* path, size_t line_no, char* line, MhModule* m)
{
    char* p = line;
    char* end_ = line + strlen(line);
    char* name = nil;
    size_t name_len = 0;
    bool is_extern = false;
    MhExportKind kind = 0;
    MhCompleteness completeness = 0;
    MhExport exp = {0};
    char* owner = nil;
    size_t owner_len = 0;
    bool is_method = false;
    bool is_instance = false;
    if (!mh_match_word(&p, end_, "export"))
    {
        mh_fatal(path, line_no, "expected export");
    }
    if (mh_match_word(&p, end_, "extern"))
    {
        is_extern = true;
    }
    if (mh_match_word(&p, end_, "procedure"))
    {
        kind = MH_KIND_PROCEDURE;
    }
    else if (mh_match_word(&p, end_, "function"))
    {
        kind = MH_KIND_FUNCTION;
    }
    else if (mh_match_word(&p, end_, "type"))
    {
        kind = MH_KIND_TYPE;
    }
    else if (mh_match_word(&p, end_, "enum"))
    {
        kind = MH_KIND_ENUM;
    }
    else if (mh_match_word(&p, end_, "var"))
    {
        kind = MH_KIND_VAR;
    }
    else if (mh_match_word(&p, end_, "const"))
    {
        kind = MH_KIND_CONST;
    }
    else if (mh_match_word(&p, end_, "define"))
    {
        kind = MH_KIND_DEFINE;
    }
    else
    {
        mh_fatal(path, line_no, "mh_parse_export_line: expected export kind");
    }
    if (!mh_read_ident(&p, end_, &name, &name_len))
    {
        mh_fatal(path, line_no, "mh_parse_export_line: expected export name");
    }
    if (mh_match_word(&p, end_, "complete"))
    {
        completeness = MH_COMPLETENESS_COMPLETE;
    }
    else if (mh_match_word(&p, end_, "incomplete"))
    {
        completeness = MH_COMPLETENESS_INCOMPLETE;
    }
    else if (mh_match_word(&p, end_, "opaque"))
    {
        completeness = MH_COMPLETENESS_OPAQUE;
    }
    else
    {
        mh_fatal(path, line_no, "mh_parse_export_line: expected complete, incomplete, or opaque");
    }
    if (mh_match_word(&p, end_, "instance"))
    {
        is_method = true;
        is_instance = true;
        if (!mh_read_ident(&p, end_, &owner, &owner_len))
        {
            mh_fatal(path, line_no, "mh_parse_export_line: expected owner type after instance");
        }
    }
    else if (mh_match_word(&p, end_, "static"))
    {
        is_method = true;
        is_instance = false;
        if (!mh_read_ident(&p, end_, &owner, &owner_len))
        {
            mh_fatal(path, line_no, "mh_parse_export_line: expected owner type after static");
        }
    }
    (exp).kind = kind;
    (exp).is_extern = is_extern;
    (exp).completeness = completeness;
    (exp).name = mh_strdup_n(name, name_len);
    (exp).name_len = name_len;
    (exp).is_method = is_method;
    (exp).is_instance = is_instance;
    (exp).method_owner = nil;
    (exp).method_owner_len = 0;
    if ((exp).name == nil)
    {
        mh_fatal(path, line_no, "mh_parse_export_line: out of memory");
    }
    if (is_method)
    {
        (exp).method_owner = mh_strdup_n(owner, owner_len);
        (exp).method_owner_len = owner_len;
        if ((exp).method_owner == nil)
        {
            mh_fatal(path, line_no, "mh_parse_export_line: out of memory (owner)");
        }
    }
    (exp).has_signature = false;
    (exp).formals = nil;
    (exp).formal_count = 0;
    (exp).has_result = false;
    mh_type_spec_clear(&(exp).result);
    (exp).is_struct = false;
    (exp).is_union = false;
    (exp).extends_name = nil;
    (exp).extends_name_len = 0;
    (exp).fields = nil;
    (exp).field_count = 0;
    (exp).is_func_type = false;
    (exp).has_alias = false;
    mh_type_spec_clear(&(exp).alias_);
    if (kind == MH_KIND_PROCEDURE || kind == MH_KIND_FUNCTION)
    {
        mh_parse_signature(path, line_no, &p, end_, &exp);
    }
    if (kind == MH_KIND_TYPE)
    {
        mh_parse_field_list(path, line_no, &p, end_, &exp);
        if (!(exp).is_struct && !(exp).is_union)
        {
            mh_parse_method_type_tail(path, line_no, &p, end_, &exp);
        }
        if (!(exp).is_struct && !(exp).is_union && !(exp).is_func_type)
        {
            mh_parse_alias_rhs(path, line_no, &p, end_, &exp);
        }
    }
    mh_module_add(m, exp);
}

static void mh_parse_line(const char* path, size_t line_no, char* line, MhModule* m)
{
    char* hash = strchr(line, '#');
    size_t i = 0;
    if (hash != nil)
    {
        (*hash) = '\0';
    }
    i = 0;
    while (line[i] != '\0' && (line[i] == ' ' || line[i] == '\t' || line[i] == '\r'))
    {
        {
            i = i + 1;
        }
    }
    if (line[i] == '\0')
    {
                return;
    }
    if (memcmp(line + i, "@module", 7) == 0)
    {
        char* p = line + i;
        char* end_ = line + strlen(line);
        char* name = nil;
        size_t name_len = 0;
        if (!mh_match_word(&p, end_, "@module"))
        {
            mh_fatal(path, line_no, "mh_parse_line: expected @module");
        }
        if (!mh_read_ident(&p, end_, &name, &name_len))
        {
            mh_fatal(path, line_no, "mh_parse_line: expected module name after @module");
        }
        if (((*m)).module_name != nil)
        {
            mh_fatal(path, line_no, "mh_parse_line: duplicate @module line");
        }
        ((*m)).module_name = name;
        ((*m)).module_name_len = name_len;
                return;
    }
    if (memcmp(line + i, "@format", 7) == 0)
    {
        char* p = line + i;
        char* end_ = line + strlen(line);
        if (!mh_match_word(&p, end_, "@format"))
        {
            mh_fatal(path, line_no, "mh_parse_line: expected @format");
        }
        while ((*p) != '\0' && ((*p) == ' ' || (*p) == '\t'))
        {
            {
                p = p + 1;
            }
        }
        if ((*p) == '\0' || !isdigit((int)(*p)))
        {
            mh_fatal(path, line_no, "mh_parse_line: expected format version number");
        }
        if (atoi(p) != 1)
        {
            mh_fatal(path, line_no, "mh_parse_line: unsupported modc-mh format version");
        }
        ((*m)).format_version = 1;
                return;
    }
    if (memcmp(line + i, "export", 6) == 0)
    {
        mh_parse_export_line(path, line_no, line + i, m);
                return;
    }
    mh_fatal(path, line_no, "mh_parse_line: unrecognized .mh line");
}

